+            schema_version = TelemetryConstants.SchemaVersion,
+            instance_id = d.InstanceId,
+            ping_type = pingType,
+            plugin_version = Plugin.Instance?.Version?.ToString() ?? "unknown",
+            jellyfin_version = JellyfinVersion ?? "unknown",
+            features = new
